import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BZk_B2cc.js";const h=JSON.parse('{"title":"F2: Dynamic Fare Matrix, Routing & Google Maps Polyline Rendering","description":"","frontmatter":{},"headers":[],"relativePath":"features/F2-dynamic-fare-routing-maps.md","filePath":"features/F2-dynamic-fare-routing-maps.md"}'),r={name:"features/F2-dynamic-fare-routing-maps.md"};function n(o,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="f2-dynamic-fare-matrix-routing-google-maps-polyline-rendering" tabindex="-1">F2: Dynamic Fare Matrix, Routing &amp; Google Maps Polyline Rendering <a class="header-anchor" href="#f2-dynamic-fare-matrix-routing-google-maps-polyline-rendering" aria-label="Permalink to &quot;F2: Dynamic Fare Matrix, Routing &amp; Google Maps Polyline Rendering&quot;">​</a></h1><h2 id="_1-description-fare-formula" tabindex="-1">1. Description &amp; Fare Formula <a class="header-anchor" href="#_1-description-fare-formula" aria-label="Permalink to &quot;1. Description &amp; Fare Formula&quot;">​</a></h2><p>When a rider enters pickup and destination addresses (<code>Home.jsx</code>), the system queries Google Geocoding for coordinates and Distance Matrix for distance and duration (<code>backend/services/maps.service.js</code>). The ride service (<code>ride.service.js</code>) applies tiered pricing formulas across vehicle categories:</p><p>$$\\text{Fare}<em>{\\text{auto}} = 30 + (\\text{dist}</em>{\\text{km}} \\times 10) + (\\text{time}<em>{\\text{min}} \\times 1)$$ $$\\text{Fare}</em>{\\text{car}} = 50 + (\\text{dist}<em>{\\text{km}} \\times 15) + (\\text{time}</em>{\\text{min}} \\times 2)$$ $$\\text{Fare}<em>{\\text{moto}} = 20 + (\\text{dist}</em>{\\text{km}} \\times 8) + (\\text{time}_{\\text{min}} \\times 0.5)$$</p><h2 id="_2-vehicle-selection-architecture" tabindex="-1">2. Vehicle Selection Architecture <a class="header-anchor" href="#_2-vehicle-selection-architecture" aria-label="Permalink to &quot;2. Vehicle Selection Architecture&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Input[Rider Inputs Addresses] --&gt; Geocode[Google Geocoding Service]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Geocode --&gt; Distance[Google Distance Matrix API]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Distance --&gt; Matrix[Compute Base + Km + Time Multipliers]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Matrix --&gt; Tiers[VehiclePanel: Auto, Car, Moto Rates]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tiers --&gt; Selection[Rider Selects Desired Vehicle]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;I built the routing and fare calculation pipeline by integrating the Google Maps Distance Matrix and Directions APIs. When a rider selects their route, the backend geocodes both points into latitude and longitude coordinates and retrieves the real-time road distance and traffic-adjusted travel duration. I then implemented a tiered fare algorithm that calculates separate prices for cars, motorcycles, and auto-rickshaws by weighting base fares, distance per kilometer, and travel time. On the frontend, <code>@react-google-maps/api</code> immediately renders the route polyline and pickup markers, giving riders clear visual feedback before they commit to booking.&quot;</p>`,8)])])}const u=a(r,[["render",n]]);export{h as __pageData,u as default};
